// === Tab: Tube ===
class Tube {
	constructor(pos,a) {
		this.pos = pos;
		this.tpos = pos.copy();
		this.opos = pos.copy();
		this.moved = false;
		this.height = 20;
		this.ang = createVector(HALF_PI,0,0);
		this.tang = createVector(HALF_PI,a,0);
		this.wilt = 1;
	}
	show() {
		push();
		translate(this.pos.x, this.pos.y, this.pos.z);
		rotateX(this.ang.x);
		rotateY(this.ang.y);
		rotateZ(this.ang.z);
		translate(this.height/2,0,0);
		scale(1.25-this.wilt/4,1,this.wilt)
		cylinder(3, this.height)
		pop();
	}
	move() {
		this.wilt = map(this.ang.x,PI/8,0,1,0.1, true);
		this.pos.lerp(this.tpos, 0.1);
		this.ang.lerp(this.tang, 0.1);
	}
}

