// For the #WCCChallenge, theme: "eroded"
let word = "erode";
let tubes = [];
let boundary = -160*word.length;
let db = 2;

function preload() {
	font = loadFont('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/default_texture.png');
}

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	let pts = font.textToPoints(word, -120*word.length, 80, 400, {
		sampleFactor: 0.08,
		simplifyThreshold: 0
	});
	for (let z = -30; z < 30; z += 20) {
		for (let i = 0; i < pts.length; i += 1) {
			let pos = createVector(pts[i].x * 0.9, pts[i].y, z);
			tubes.push(new Tube(pos));
		}
	}
}

function draw() {
	orbitControl();
	rotateY((PI / 18) * sin(frameCount / 180));
	rotateX(QUARTER_PI - (QUARTER_PI) * cos(frameCount / 180));
	background('ivory');
	fill(0, 100);
	noStroke();
	for (let tube of tubes) {
		tube.show();
		tube.move();
		if (db > 0 && tube.moved == false && tube.tpos.x + tube.pos.y - tube.tpos.z < boundary) {
			tube.tpos.x = tube.opos.x - abs(randomGaussian() * 48);
			tube.tpos.y = tube.opos.y - abs(randomGaussian() * 48);
			tube.tpos.z = -30;
			tube.tang = createVector(0, 0, random(PI));
			tube.moved = true;
		} else if (db < 0 && tube.moved == false && tube.tpos.x + tube.pos.y - tube.tpos.z > boundary) {
			tube.tpos = tube.opos.copy();
			tube.tang = createVector(HALF_PI, 0, 0);
			tube.moved = true;
		}
	}
	boundary += db;
	if (abs(boundary) > 160*word.length) {
		for (let tube of tubes) {
			tube.moved = false;
		}
		db = -db;
	}
}
